 for(const c of m.components){c.kind=c.dex.length?'dex-bearing':'resource-or-native-only';c.resourceHandling='All resources, binary XML and native libraries preserved byte-for-byte. DEX/Java decompilation is applicable only when classes.dex is present; native Flutter AOT remains binary, not recovered original Dart source.';}
